insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-en-a1-fe7cefb9642c', 'en', 'A1', 'My Friends and I', 'I am Ana, and this is my friend Paul. He is from England. He is a teacher. She is Maria, my sister. She is a nurse. We are in a big city. It is very beautiful. You are welcome here.

My classmates are from many countries. They are very friendly. We are happy together. Paul is an English teacher, and Maria is a nurse. I am a student. We are not from the same city, but we are friends. Are you a student too? I think you are.

Today we are at a café. It is small but nice. We are very happy. This is our first meeting. You are our new friend. Welcome!', '[{"answer_index":1,"explanation_pt_br":"O texto diz: ''He is from England.'' O pronome ''He'' refere-se a Paul, então Paul é da Inglaterra.","options":["Ana","Paul","Maria","We"],"prompt":"Who is from England?"},{"answer_index":2,"explanation_pt_br":"No texto: ''She is a nurse.'' ''She'' refere-se a Maria. Portanto, Maria é enfermeira.","options":["She is a teacher.","She is a student.","She is a nurse.","She is a doctor."],"prompt":"What does Maria do?"},{"answer_index":0,"explanation_pt_br":"No último parágrafo, ''we'' se refere a Ana, Paul e Maria. Eles estão em um café. ''You'' é a pessoa a quem eles dão as boas-vindas.","options":["Ana, Paul and Maria","Only Ana","The classmates from many countries","You"],"prompt":"Who is at the café in the last paragraph?"}]'::jsonb, 0, true)
