insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-en-a1-9d6c53952f78', 'en', 'A1', 'My New Friends', 'I am Ana, and I am from Brazil. I live in São Paulo with my family. My father is a teacher. He is very patient. My mother is a nurse. She is kind and beautiful. I have a brother. He is fifteen years old. I also have a sister. She is a student.

We are a happy family. My friends are interesting. John is from Canada. He is an engineer. Maria is from Portugal. She is a doctor. They are in my English class. We are classmates. You are here too! I think you are a nice person.

Our teacher is Mr. Smith. He is from the United States. He is funny and smart. We are learning English together. It is a new language for us. I am excited, and we are ready to learn.', '[{"answer_index":0,"explanation_pt_br":"No texto, Ana diz: \"I am from Brazil.\" Portanto, ela é do Brasil.","options":["Brazil","Portugal","Canada","United States"],"prompt":"Where is Ana from?"},{"answer_index":1,"explanation_pt_br":"O texto diz: \"Maria is from Portugal. She is a doctor.\" Então Maria é médica.","options":["She is a teacher.","She is a doctor.","She is a nurse.","She is an engineer."],"prompt":"What does Maria do?"},{"answer_index":3,"explanation_pt_br":"John e Maria são duas pessoas, então usamos o pronome ''they'' (eles/elas).","options":["He","She","We","They"],"prompt":"Which pronoun can replace ''John and Maria'' in the sentence ''John and Maria are in my English class''?"}]'::jsonb, 0, true)
