insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-en-a1-cc7e716e50a6', 'en', 'A1', 'My Friends and I', 'Hello! My name is Ana. I am from Brazil. This is my friend Ben. He is from the United States. She is my sister Lia. We are students. They are our teachers. You are in our class too. It is a nice class.

We are happy. I am tall. He is funny. She is smart. They are kind. We are all friends. We like English. You like English too. It is a new language for us. We practice every day. My teacher says, ''You are good students!'' We are proud.

Lia and I are from São Paulo. Ben is from New York. They are far from home. We are in London now. It is a big city. We are here for one year. You can visit us! Are you ready? We are ready.', '[{"answer_index":0,"explanation_pt_br":"No texto, ''He is from the United States'' se refere ao Ben, que é amigo da Ana.","options":["Ben","Ana","Lia","The teacher"],"prompt":"In the text, who is ''he''?"},{"answer_index":0,"explanation_pt_br":"''Lia and I'' (Lia e eu) equivale a ''nós'', então o pronome correto é ''we''.","options":["We","They","You","It"],"prompt":"Which pronoun can replace ''Lia and I''?"},{"answer_index":0,"explanation_pt_br":"A frase fala diretamente com o leitor, então ''you'' significa ''você''.","options":["The reader","Ben","Lia","The teachers"],"prompt":"In ''You are in our class too,'' who is ''you''?"}]'::jsonb, 0, true)
