insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-en-a1-53407bceaca8', 'en', 'A1', 'My Family and I', 'Hello! My name is Ana. I am from Brazil. I have a big family. This is my father. He is a teacher. This is my mother. She is a doctor. They are very busy. We live in a small house. My father is tall. My mother is beautiful. They love us.

My brother is called Pedro. He is twelve years old. He likes soccer. My sister is called Sofia. She is eight. She likes dolls. Our dog is named Rex. It is very friendly. You can visit us on Saturday. We are happy. Pedro and I play video games. We are good friends.', '[{"answer_index":1,"explanation_pt_br":"''They'' se refere ao pai e à mãe de Ana, mencionados anteriormente como ''father'' e ''mother''.","options":["Ana and her brother","Ana''s parents","Ana and her sister","Pedro and Sofia"],"prompt":"In the text, ''They are very busy.'' Who are ''They''?"},{"answer_index":2,"explanation_pt_br":"''It'' se refere ao cachorro Rex, que é apresentado na frase anterior.","options":["The house","The video game","The dog","The school"],"prompt":"In the text, ''It is very friendly.'' What is ''It''?"},{"answer_index":0,"explanation_pt_br":"A frase anterior diz ''Pedro and I play video games.'' Portanto, ''We'' significa Ana e Pedro.","options":["Ana and Pedro","Ana''s parents","Pedro and Sofia","Ana and Sofia"],"prompt":"In the text, ''We are good friends.'' Who are ''We''?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-en-a1-36b5d5e65493', 'en', 'A1', 'Our Day at School', 'Hello! My name is Ana. I am a teacher. I have a small family. This is my husband, Pedro. He is an engineer. We have two children: a son and a daughter. They are students. My son, Lucas, is ten years old. He likes soccer. My daughter, Sofia, is eight. She likes music.

Our dog, Rex, is very funny. It likes to play in the park. You are my new friend. I am happy to meet you. Look at us! We are a happy family. I love my family.

They are in the classroom now. We are ready to learn English. You can see our photos. They are on the wall. We have a nice day today.', '[{"answer_index":0,"explanation_pt_br":"Pedro é o marido da Ana. Como Pedro é homem, usamos o pronome ''He''.","options":["He is my husband.","She is my husband.","It is my husband.","You are my husband."],"prompt":"Who is Pedro?"},{"answer_index":0,"explanation_pt_br":"Lucas e Sofia são duas pessoas (plural). Usamos ''They'' para falar de várias pessoas.","options":["They are students.","He is a student.","She is a student.","We are students."],"prompt":"Who are Lucas and Sofia?"},{"answer_index":0,"explanation_pt_br":"Rex é o cachorro da família. Para animais e objetos, usamos ''It''.","options":["It likes to play in the park.","He likes to play in the park.","She likes to play in the park.","They like to play in the park."],"prompt":"What does Rex like to do?"}]'::jsonb, 0, true)
