insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-en-a1-7d7ac1cc4fa6', 'en', 'A1', 'Maria and John', 'Maria is a teacher. She lives in São Paulo. She has a dog. It is small and brown. John is her friend. He is an engineer. He works in Rio de Janeiro. They talk on the phone every week. They are good friends.

We are students of English. We study together. You are a student too. You read this lesson. I am happy to learn with you. It is a beautiful day. The sun is bright.

They are Maria''s students. They are from Brazil. They love English. She teaches them new words. He visits her on weekends. We all learn together. This is our class.', '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''Maria is a teacher.'' Portanto, Maria é professora.","options":["A teacher","An engineer","A student","A dog"],"prompt":"Who is Maria?"},{"answer_index":1,"explanation_pt_br":"No texto, Maria é a professora que ensina novas palavras. ''She'' (ela) refere-se a Maria.","options":["John","Maria","The dog","The students"],"prompt":"What does ''She'' refer to in ''She teaches them new words''?"},{"answer_index":0,"explanation_pt_br":"O texto diz que Maria e John falam ao telefone toda semana. ''They'' (eles) refere-se a Maria and John.","options":["Maria and John","The students","You and I","The dog and the sun"],"prompt":"In the sentence ''They talk on the phone every week'', who are ''they''?"}]'::jsonb, 0, true)
