insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-it-a1-2de20dbddc68', 'it', 'A1', 'Un viaggio in Italia', 'Ciao! Oggi parlo del mio viaggio in Italia. Io visito Roma e Milano. Roma è una città bellissima. Ci sono i musei e le piazze. Il Colosseo è un monumento antico. La fontana di Trevi è molto famosa.

Milano è una città moderna. Ci sono i negozi e le università. L''università di Milano è grande. Il mio hotel è vicino alla stazione. Le camere sono pulite e confortevoli.

Mi piace molto la cucina italiana. Ogni giorno mangio la pizza o la pasta. Gli italiani sono molto gentili. I ristoranti sono ottimi. Nel mio viaggio, io uso la macchina fotografica. Le foto sono belle. Alla fine, io compro alcuni regali per la mia famiglia. I regali sono piccoli e carini. Questo viaggio è indimenticabile!', '[{"answer_index":0,"explanation_pt_br":"O Coliseu é um monumento antigo, como diz o texto.","options":["Un monumento","Una città","Un negozio","Un ristorante"],"prompt":"Che cosa è il Colosseo?"},{"answer_index":0,"explanation_pt_br":"A palavra ''piazza'' é feminina singular; o plural é ''piazze'' com o artigo feminino plural ''le''.","options":["la piazza","il piazza","la piazzo","il piazzo"],"prompt":"Nel testo, ''le piazze'' è il plurale di quale parola?"},{"answer_index":1,"explanation_pt_br":"A palavra ''museo'' é masculina, pois usamos o artigo ''il''. As outras são femininas.","options":["città","museo","fontana","camere"],"prompt":"Quale di queste parole è maschile?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-it-a1-9e0205d59ed0', 'it', 'A1', 'La mia università', 'Salve! Mi chiamo Marco. Abito a Milano. Studio all''università. Ogni giorno vado a piedi. L''università è grande e moderna. Ci sono molti studenti. I professori sono bravi. La biblioteca è silenziosa. I libri sono interessanti. Le lezioni cominciano alle nove.

Nella mia classe ci sono dieci studenti. Loro sono di paesi diversi. La mia compagna è brasiliana. Il mio compagno è francese. Noi parliamo italiano. Le professoresse sono gentili. Oggi abbiamo un esame. L''esame è facile.

Dopo le lezioni, mangiamo nella mensa. La pizza è buona. I panini sono buoni. Le bevande sono fredde. L''acqua è importante. Io studio sempre. L''italiano è una lingua bella.', '[{"answer_index":1,"explanation_pt_br":"O texto diz: \"Abito a Milano.\" Portanto, Marcos mora em Milão.","options":["A Roma","A Milano","A Firenze","A Napoli"],"prompt":"Dove abita Marco?"},{"answer_index":1,"explanation_pt_br":"O texto diz: \"Nella mia classe ci sono dieci studenti.\" Portanto, há dez estudantes.","options":["cinque","dieci","venti","dodici"],"prompt":"Quanti studenti ci sono nella classe di Marco?"},{"answer_index":2,"explanation_pt_br":"No texto: \"I panini sono buoni.\" Panini é masculino plural, então o adjetivo concorda: buoni.","options":["buona","buone","buoni","buono"],"prompt":"Completa la frase: \"I panini sono ______.\""}]'::jsonb, 0, true)
